
import React, { useContext, useState } from 'react';
import './Create.css';
import { useHistory } from 'react-router-dom';
import { FirebaseContext, AuthContext } from '../../store/Context';

const Create = () => {
  const { firebase } = useContext(FirebaseContext);
  const { user } = useContext(AuthContext);
  const history = useHistory();

  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [price, setPrice] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async e => {
    e.preventDefault();
    setError('');

    if (!user) {
      history.push('/login');
      return;
    }

    if (
      !name.trim() ||
      !category.trim() ||
      price === '' ||
      !Number.isFinite(Number(price)) ||
      Number(price) < 0 ||
      !imageUrl.trim()
    ) {
      setError('Please complete every field and enter a product image URL.');
      return;
    }

    let parsedUrl;

    try {
      parsedUrl = new URL(imageUrl.trim());
    } catch {
      setError('Please enter a valid image URL.');
      return;
    }

    if (parsedUrl.protocol !== 'https:' && parsedUrl.protocol !== 'http:') {
      setError('The image URL must start with https:// or http://.');
      return;
    }

    setBusy(true);

    try {
      await firebase.firestore().collection('products').add({
        name: name.trim(),
        category: category.trim(),
        price: String(price),
        url: imageUrl.trim(),
        userId: user.uid,
        createdAt: new Date().toDateString()
      });

      history.push('/');
    } catch (err) {
      setError(err.message || 'Your listing could not be published. Please try again.');
    } finally {
      setBusy(false);
    }
  };

  return (
    <main className="centerDiv createForm">
      <span className="siteEyebrow">Share something good</span>

      <h1
        style={{
          fontFamily: 'Manrope,sans-serif',
          fontSize: 28,
          letterSpacing: '-1px',
          margin: '7px 0'
        }}
      >
        Create a listing
      </h1>

      <p style={{ color: 'var(--muted)', fontSize: 14, marginTop: 0 }}>
        Add a few details so the right buyer can find it.
      </p>

      <form onSubmit={handleSubmit}>
        <label htmlFor="listing-name">What are you selling?</label>
        <input
          className="input"
          id="listing-name"
          type="text"
          value={name}
          onChange={e => setName(e.target.value)}
          placeholder="e.g. iPhone 13, mountain bike"
          maxLength="100"
          required
        />

        <label htmlFor="listing-category">Category</label>
        <select
          className="input"
          id="listing-category"
          value={category}
          onChange={e => setCategory(e.target.value)}
          required
        >
          <option value="">Choose a category</option>
          {[
            'Cars',
            'Motorcycles',
            'Mobile phones',
            'Electronics',
            'Furniture',
            'Fashion',
            'Property',
            'Jobs',
            'Other'
          ].map(c => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>

        <label htmlFor="listing-price">Price</label>
        <input
          className="input"
          id="listing-price"
          type="number"
          min="0"
          step="1"
          value={price}
          onChange={e => setPrice(e.target.value)}
          placeholder="Enter your price"
          required
        />

        <label htmlFor="listing-image-url">Product image URL</label>
        <input
          className="input"
          id="listing-image-url"
          type="url"
          value={imageUrl}
          onChange={e => {
            setImageUrl(e.target.value);
            setError('');
          }}
          placeholder="https://i.ibb.co/.../photo.jpg"
          required
        />

        {imageUrl.trim() && (
          <div style={{ margin: '12px 0' }}>
            <p style={{ fontSize: 13, color: 'var(--muted)' }}>
              Image preview
            </p>
            <img
              src={imageUrl.trim()}
              alt="Product preview"
              width="220"
              height="180"
              style={{
                maxWidth: '100%',
                objectFit: 'contain',
                borderRadius: 8
              }}
              onError={e => {
                e.currentTarget.style.display = 'none';
              }}
              onLoad={e => {
                e.currentTarget.style.display = 'block';
              }}
            />
          </div>
        )}

        {error && (
          <p className="authError" role="alert">
            {error}
          </p>
        )}

        <button className="uploadBtn" type="submit" disabled={busy}>
          {busy ? 'Publishing listing...' : 'Publish listing'}
        </button>
      </form>
    </main>
  );
};

export default Create;
