import React, { useState, useContext } from 'react';
import { Link, useHistory } from 'react-router-dom';
import Logo from '../../olx-logo.png';
import './Signup.css';
import { FirebaseContext } from '../../store/Context';
export default function Signup() {
  const history = useHistory(); const [username, setUsername] = useState(''); const [email, setEmail] = useState(''); const [phone, setPhone] = useState(''); const [password, setPassword] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const { firebase } = useContext(FirebaseContext);
  const handleSubmit = async e => { e.preventDefault(); setBusy(true); setError(''); let createdUser = null; try { const result = await firebase.auth().createUserWithEmailAndPassword(email, password); createdUser = result.user; await createdUser.updateProfile({displayName:username.trim()}); await firebase.firestore().collection('users').add({id:createdUser.uid, username:username.trim(), phone:phone.trim()}); history.push('/'); } catch (err) { if (createdUser) { /* Account was created; report the profile save issue without hiding it. */ } setError(err.message || 'Could not create your account. Please try again.'); } finally { setBusy(false); } };
  return <main className="signupParentDiv"><img src={Logo} alt="OLX logo"/><span className="siteEyebrow" style={{display:'block',textAlign:'center'}}>Join the community</span><h1 style={{fontFamily:'Manrope,sans-serif',textAlign:'center',fontSize:27,margin:'7px 0 22px'}}>Create your account</h1><form onSubmit={handleSubmit}><label htmlFor="signup-name">Your name</label><input className="input" type="text" autoComplete="name" value={username} onChange={e => setUsername(e.target.value)} id="signup-name" placeholder="How should we call you?" required/><label htmlFor="signup-email">Email address</label><input className="input" type="email" autoComplete="email" value={email} onChange={e => setEmail(e.target.value)} id="signup-email" placeholder="you@example.com" required/><label htmlFor="signup-phone">Phone number (optional)</label><input className="input" type="tel" autoComplete="tel" value={phone} onChange={e => setPhone(e.target.value)} id="signup-phone" placeholder="Your contact number"/><label htmlFor="signup-password">Password</label><input className="input" type="password" autoComplete="new-password" minLength="6" value={password} onChange={e => setPassword(e.target.value)} id="signup-password" placeholder="At least 6 characters" required/>{error && <p className="authError" role="alert">{error}</p>}<button type="submit" disabled={busy}>{busy ? 'Creating account…' : 'Create account'}</button></form><p style={{textAlign:'center',color:'var(--muted)',fontSize:13}}>Already have an account? <Link to="/login" style={{color:'var(--teal)',fontWeight:800}}>Sign in</Link></p><Link to="/" style={{display:'block',textAlign:'center',fontSize:13,color:'var(--muted)'}}>← Back to marketplace</Link></main>;
}
